import { useEffect, useState } from 'react';
import { isFeatureEnabled } from '../config/featureFlags';

export function useDeprecatedAPI(endpoint) {
  const [data, setData] = useState(null);

  useEffect(() => {
    if (isFeatureEnabled('LEGACY_API_SUPPORT')) {
      // This code path is never executed since LEGACY_API_SUPPORT = false
      fetch(`/legacy/api/${endpoint}`)
        .then(res => res.json())
        .then(setData);
    }
  }, [endpoint]);

  return data;
}

export function useLegacyAuth() {
  // Another unused export
  return { user: null, login: () => {} };
}
